// GetAssignedOrders is the resolver for the getAssignedOrders field.
func (r *queryResolver) GetAssignedOrders(ctx context.Context) ([]*model.Order, error) {
	var assignedRiders []*model.AssignRider

	// Retrieve the driver (user) ID from the context
	driverIDStr, err := r.Query().GetID(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to get driver ID: %v", err)
	}

	userUUID, err := uuid.Parse(*driverIDStr)
	if err != nil {
		return nil, fmt.Errorf("invalid driver ID: %w", err)
	}

	// Calculate the timestamp for 6 hours ago
	sixHoursAgo := time.Now().Add(-6 * time.Hour)

	// Step 1: Get assigned orders for this rider
	if err := r.DB.Where("rider_id = ? AND created_at >= ?", userUUID, sixHoursAgo).
		Find(&assignedRiders).Error; err != nil {
		return nil, fmt.Errorf("failed to fetch assigned orders: %w", err)
	}

	// Extract order IDs from assignedRiders
	orderIDs := make([]uuid.UUID, 0, len(assignedRiders))
	for _, ar := range assignedRiders {
		if ar.OrderID != nil {
			orderID, err := uuid.Parse(*ar.OrderID)
			if err == nil {
				orderIDs = append(orderIDs, orderID)
			}
		}
	}

	// Step 2: Fetch orders that match the assigned order IDs
	var orders []*model.Order
	if len(orderIDs) > 0 {
		if err := r.DB.Preload("Items.Product").
			Where("id IN (?)", orderIDs).
			Find(&orders).Error; err != nil {
			return nil, fmt.Errorf("failed to fetch order details: %w", err)
		}
	}

	return orders, nil
}

